    display: flex;
    align-items: center;
    justify-content: center;
}

.hero {
    @include flex-center;
    min-height: 100vh;
}

// Functions and operations
@function rem($px) {
    @return $px / 16px * 1rem;
}

.title { font-size: rem(24px); }   /* 1.5rem */

// Loops
@for $i from 1 through 12 {
    .col-#{$i} { width: ($i / 12) * 100%; }
}

// Conditionals
@mixin theme($mode) {
    @if $mode == dark {
        background: #222;
        color: #eee;
    } @else {
        background: #fff;
        color: #333;
    }
}

