}

@layer base {
    :root {
        --color-bg: #fff;
        --color-text: #333;
        --color-primary: #3498db;
        --font-sans: system-ui, -apple-system, sans-serif;
    }
    body {
        background: var(--color-bg);
        color: var(--color-text);
        font-family: var(--font-sans);
