.nav {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 2rem;
    background: var(--color-bg);
    border-block-end: 1px solid #eee;
}
.nav__logo { font-weight: bold; font-size: 1.25rem; }
.nav__hamburger { display: none; cursor: pointer; }
.nav__menu {
    display: flex;
    gap: 2rem;
    list-style: none;
}
.nav__link {
    text-decoration: none;
    color: var(--color-text);
    position: relative;
    padding-block-end: 0.25rem;
}
.nav__link::after {
    content: "";
    position: absolute;
    inset-block-end: 0;
    inset-inline: 0;
    block-size: 2px;
    background: var(--color-primary);
    transform: scaleX(0);
    transform-origin: inline-start;
    transition: transform 0.3s ease;
}
.nav__link:hover::after { transform: scaleX(1); }

@media (max-width: 768px) {
    .nav__hamburger { display: flex; flex-direction: column; gap: 5px; }
    .nav__hamburger span { inline-size: 25px; block-size: 3px; background: var(--color-text); }
    .nav__menu {
        position: absolute;
        inset-block-start: 100%;
        inset-inline: 0;
        flex-direction: column;
        gap: 0;
        background: var(--color-bg);
        padding: 1rem 2rem;
        transform: scaleY(0);
        transform-origin: block-start;
        transition: transform 0.3s ease;
    }
    .nav__toggle:checked ~ .nav__menu { transform: scaleY(1); }
}

