class Point {
    final double x;
    final double y;

    // Constructor
    Point(this.x, this.y);

    // Named constructor
    Point.origin() : x = 0, y = 0;

    // Redirecting constructor
    Point.alongXAxis(double x) : this(x, 0);

    // Method
    double distanceTo(Point other) {
        var dx = x - other.x;
        var dy = y - other.y;
        return sqrt(dx * dx + dy * dy);
    }

    // Getter
    bool get isOrigin => x == 0 && y == 0;

    // toString
    @override
    String toString() => 'Point($x, $y)';
}

