// Deep merge requires manual handling or a library like lodash.merge
const deepMerge = (a, b) => {
  const result = { ...a }
  for (const key in b) {
    if (isObject(a[key]) && isObject(b[key])) {
      result[key] = deepMerge(a[key], b[key])
    } else {
      result[key] = b[key]
    }
  }
  return result
}

