class TodoApp {
  #todos = []

  add(text) {
    this.#todos = [...this.#todos, { id: crypto.randomUUID(), text, done: false }]
    this.save()
    this.render()
  }

  toggle(id) {
    this.#todos = this.#todos.map(t => t.id === id ? { ...t, done: !t.done } : t)
    this.save()
    this.render()
  }

  remove(id) {
    this.#todos = this.#todos.filter(t => t.id !== id)
    this.save()
    this.render()
