class CachedProperty:
    def __init__(self, func):
        self.func = func
        self.cache = {}

    def __get__(self, instance, owner):
        if instance is None:
            return self
        if id(instance) not in self.cache:
            self.cache[id(instance)] = self.func(instance)
        return self.cache[id(instance)]

class Report:
    def __init__(self, data):
