function SignupForm() {
  const [form, setForm] = useState({ email: '', password: '' })
  const [errors, setErrors] = useState({})
  const [submitting, setSubmitting] = useState(false)

  function validate(values) {
    const next = {}
    if (!values.email.includes('@')) next.email = 'Enter a valid email address'
    if (values.password.length < 8) next.password = 'Password must be at least 8 characters'
    return next
  }

  function handleBlur(e) {
    const fieldErrors = validate(form)
    setErrors(prev => ({ ...prev, [e.target.name]: fieldErrors[e.target.name] }))
  }

  async function handleSubmit(e) {
    e.preventDefault()
    const fieldErrors = validate(form)
    setErrors(fieldErrors)
    if (Object.keys(fieldErrors).length > 0) return

    setSubmitting(true)
    try {
      await submitSignup(form)
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <input
        name="email"
        value={form.email}
        onChange={e => setForm(prev => ({ ...prev, email: e.target.value }))}
        onBlur={handleBlur}
      />
      {errors.email && <p className="error">{errors.email}</p>}

      <input
        name="password"
        type="password"
        value={form.password}
        onChange={e => setForm(prev => ({ ...prev, password: e.target.value }))}
        onBlur={handleBlur}
      />
      {errors.password && <p className="error">{errors.password}</p>}

      <button type="submit" disabled={submitting}>
        {submitting ? 'Signing up…' : 'Sign Up'}
      </button>
    </form>
  )
}

