}
impl ConfigBuilder {
    fn new() -> Self { ConfigBuilder { host: None, port: None, timeout: None } }
    fn host(mut self, h: String) -> Self { self.host = Some(h); self }
    fn port(mut self, p: u16) -> Self { self.port = Some(p); self }
