  CONSTRAINT unique_email UNIQUE (email)
);

CREATE TABLE products (
  id         BIGSERIAL PRIMARY KEY,
  price      NUMERIC(10, 2) NOT NULL,
  qty        INTEGER NOT NULL,
  total      NUMERIC(10, 2) GENERATED ALWAYS AS (price * qty) STORED
);

