## Deduplication (keep one row per group)

::code-wrapper{language="sql"}
```sql
-- Keep the most recent row per user, delete the rest
DELETE FROM events
WHERE id IN (
  SELECT id FROM (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY created_at DESC) AS rn
    FROM events
  ) t WHERE rn > 1
);
``

ALTER TABLE orders SET (
  autovacuum_vacuum_scale_factor = 0.05,   -- vacuum at 5% dead, not 20%
  autovacuum_vacuum_cost_limit = 1000      -- let autovacuum work faster
);

WITH ranked AS (
  SELECT customer_id, id, amount,
    ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY amount DESC) AS rn
  FROM orders
)
SELECT customer_id, id, amount FROM ranked WHERE rn <= 3 ORDER BY customer_id, rn;

